<?php declare(strict_types=1);session_start();if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$nombre=trim((string)($_POST['nombre']??''));$desc=trim((string)($_POST['descripcion']??''));$orden=max(0,(int)($_POST['orden']??0));if($nombre===''){http_response_code(400);exit('El nombre es obligatorio.');}$slug=trim((string)preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$nombre))),'-');$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('INSERT INTO galeria_categorias(nombre,slug,descripcion,orden) VALUES(?,?,?,?)');$q->execute([$nombre,$slug,$desc,$orden]);header('Location: galeria-categorias-admin.php?created=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo crear la categoría.');}
